/* Palette as space-separated RGB so Tailwind can apply opacity (bg-brand/20).
   Light is the default; dark applies with the system setting unless a theme is chosen explicitly. */
:root {
  --page: 241 239 254;
  --card: 255 255 255;
  --ink: 43 38 80;
  --mute: 104 98 148;
  --line: 226 222 250;
  --soft: 236 233 255;
